import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import produce from 'immer';
import { CascaderSelect } from '@alifd/next';

// initial plain data
const initialData = [
  {
    value: 'a',
    label: 'A',
    children: [
      { value: 'b', label: 'B' }
    ]
  }
];

function App() {
  const [data, setData] = useState([]);

  useEffect(() => {
    // produce() will return a frozen object in development (autoFreeze enabled)
    const frozenData = produce(initialData, draft => {
      // no mutations here, but the returned `frozenData` is immutable
    });
    setData(frozenData);
  }, []);

  const handleChange = () => {};

  return (
    <div style={{ padding: 20 }}>
      <h3>Immer-frozen DataSource → CascaderSelect</h3>
      <CascaderSelect dataSource={data} onChange={handleChange} />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
